        JSONObject contactPolicy=null;if(skill!=null&&skill.has("contactPolicy")){contactPolicy=contactStudy.profile(skill.getJSONObject("contactPolicy").getString("id"));if(!contactStudy.activeProfile().similar(contactPolicy))throw new IllegalStateException("This retained skill requires its original validated contact controller active; restore it or use a baseline task");}else if(input.optBoolean("useContactController"))contactPolicy=contactStudy.activeProfile();
