        if(runtime.equals(PushRuntime.CONTACT)&&(input.optDouble("initialForceN",8)!=8||input.optDouble("maxForceN",32)!=32))throw new IllegalArgumentException("Validated contact controller uses original8/32N conditions; explicit force changes require a different evaluation");
